:root {
  --bg: #0b1020;
  --bg-elev: #11182d;
  --bg-soft: #16213a;
  --border: rgba(148, 163, 184, 0.18);
  --text: #e5eefc;
  --muted: #94a3b8;
  --brand: #60a5fa;
  --brand-2: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;
  --ring: rgba(96, 165, 250, 0.35);
}

html, body {
  min-height: 100%;
}

body {
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(96, 165, 250, 0.16), transparent 32%),
    radial-gradient(circle at top right, rgba(34, 197, 94, 0.10), transparent 28%),
    linear-gradient(180deg, #0b1020 0%, #0f172a 100%);
}

* {
  box-sizing: border-box;
}

button, .card, .panel, .table-row {
  transition: background-color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease, opacity 180ms ease;
}

button:hover, .card:hover, .panel:hover {
  transform: translateY(-1px);
}

button:active {
  transform: translateY(0);
}

button {
  max-width: 100%;
}

input, textarea, select {
  background-color: #0f172a;
  color: #e5eefc;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  max-width: 100%;
  width: 100%;
}

input::placeholder, textarea::placeholder {
  color: #64748b;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: rgba(96, 165, 250, 0.8);
  box-shadow: 0 0 0 4px var(--ring);
}

input[disabled], textarea[disabled], select[disabled] {
  background-color: #111827;
  color: #94a3b8;
  opacity: 0.8;
}

.view-enter {
  animation: fadeIn 180ms ease-out both;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card, .panel {
  background: rgba(17, 24, 39, 0.72);
  border: 1px solid var(--border);
  backdrop-filter: blur(10px);
  border-radius: 1rem;
  max-width: 100%;
}

.badge {
  background: rgba(96, 165, 250, 0.16);
  color: #bfdbfe;
  border: 1px solid rgba(96, 165, 250, 0.28);
  border-radius: 999px;
  padding: 0.25rem 0.6rem;
  font-size: 0.75rem;
}

.table-wrap {
  max-width: 100%;
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  color: var(--text);
  min-width: 100%;
}

th, td {
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  text-align: left;
  vertical-align: middle;
}

th {
  color: #cbd5e1;
  font-weight: 600;
  background: rgba(15, 23, 42, 0.7);
}

tbody tr:hover {
  background: rgba(96, 165, 250, 0.08);
}

.entity-switcher {
  max-width: 100%;
}

@media (max-width: 420px) {
  body {
    font-size: 14px;
  }

  .card, .panel {
    border-radius: 0.875rem;
  }

  th, td {
    padding: 0.625rem 0.7rem;
  }
}

(() => {
  const AUTH_KEY = 'app:auth';
  const ENT_KEY = 'app:entities';
  const INV_KEY = 'app:invoices';

  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));

  const ENTITIES_SEED = [
    { id: 'ent_acme_us', name: 'Acme US', currency: 'USD' },
    { id: 'ent_acme_uk', name: 'Acme UK', currency: 'GBP' },
    { id: 'ent_acme_mfg', name: 'Acme Manufacturing', currency: 'USD' }
  ];

  const INVOICES_SEED = [
    { id: 'inv_1', entityId: 'ent_acme_us', vendor: 'Office Depot', amount: 842.13, status: 'Draft', reason: '', history: [] },
    { id: 'inv_2', entityId: 'ent_acme_us', vendor: 'Global Freight Co', amount: 12850.55, status: 'Pending Approval', reason: '', history: [{ role: 'role-clerk', action: 'Submitted', reason: null, at: '2025-05-02T09:14:00Z' }] },
    { id: 'inv_3', entityId: 'ent_acme_uk', vendor: 'Stationery Hub', amount: 310.40, status: 'Pending Approval', reason: '', history: [{ role: 'role-clerk', action: 'Submitted', reason: null, at: '2025-05-03T10:02:00Z' }] },
    { id: 'inv_4', entityId: 'ent_acme_mfg', vendor: 'Cloud Services Inc', amount: 6240.00, status: 'Pending Approval', reason: '', history: [{ role: 'role-clerk', action: 'Submitted', reason: null, at: '2025-05-03T11:40:00Z' }] },
    { id: 'inv_5', entityId: 'ent_acme_us', vendor: 'Paper Supply Co', amount: 149.99, status: 'Pending Approval', reason: '', history: [{ role: 'role-clerk', action: 'Submitted', reason: null, at: '2025-05-04T08:22:00Z' }] },
    { id: 'inv_6', entityId: 'ent_acme_uk', vendor: 'TravelLink', amount: 982.75, status: 'Approved', reason: '', history: [{ role: 'role-manager', action: 'Approved', reason: null, at: '2025-05-01T15:20:00Z' }] },
    { id: 'inv_7', entityId: 'ent_acme_mfg', vendor: 'Parts Unlimited', amount: 4180.00, status: 'Paid', reason: '', history: [] },
    { id: 'inv_8', entityId: 'ent_acme_us', vendor: 'Payroll Services', amount: 2200.00, status: 'Pending Approval', reason: '', history: [{ role: 'role-clerk', action: 'Submitted', reason: null, at: '2025-05-05T09:00:00Z' }] },
    { id: 'inv_9', entityId: 'ent_acme_uk', vendor: 'Marketing Studio', amount: 760.00, status: 'Paid', reason: '', history: [] },
    { id: 'inv_10', entityId: 'ent_acme_mfg', vendor: 'Safety First LLC', amount: 515.25, status: 'Rejected', reason: 'Invoice mismatch', history: [{ role: 'role-controller', action: 'Rejected', reason: 'Invoice mismatch', at: '2025-04-28T13:45:00Z' }] }
  ];

  const ROLE_LABELS = { 'role-clerk': 'AP Clerk', 'role-manager': 'AP Manager', 'role-controller': 'Controller' };
  const MANAGER_LIMIT = 10000;
  const state = { auth: null, entities: [], invoices: [], activeTab: 'invoices' };
  let chosenRole = 'role-clerk';

  const read = (key, fallback) => { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch { return fallback; } };
  const write = (key, value) => localStorage.setItem(key, JSON.stringify(value));
  const seedIfEmpty = () => {
    if (!read(ENT_KEY, []).length) write(ENT_KEY, ENTITIES_SEED);
    if (!read(INV_KEY, []).length) write(INV_KEY, INVOICES_SEED);
  };

  const money = (n) => '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const role = () => state.auth?.role || 'role-clerk';
  const entityName = (id) => state.entities.find((e) => e.id === id)?.name || id;
  const currentEntityId = () => $('#entity-switcher')?.value || '';

  // ── Auth ────────────────────────────────────────────────────────────
  const load = () => {
    seedIfEmpty();
    state.auth = read(AUTH_KEY, null);
    state.entities = read(ENT_KEY, []);
    state.invoices = read(INV_KEY, []);
    if (!state.auth || !state.auth.role || !state.auth.token) return showLogin();
    showApp();
  };

  const showLogin = () => { $('#login-view').hidden = false; $('#app-view').hidden = true; };
  const showApp = () => {
    $('#login-view').hidden = true;
    $('#app-view').hidden = false;
    renderEntitySwitcher();
    setTab('invoices');
    render();
  };

  const login = () => {
    const em = ($('#login-email')?.value || '').trim().toLowerCase();
    const pw = $('#login-password')?.value || '';
    if (em !== 'demo@example.com' || pw !== 'demo') {
      $('#login-error').textContent = 'Wrong email or password. Try demo@example.com / demo.';
      return;
    }
    state.auth = { token: 'tok_' + Date.now(), email: em, role: chosenRole };
    write(AUTH_KEY, state.auth);
    showApp();
  };

  const logout = () => {
    state.auth = null;
    localStorage.removeItem(AUTH_KEY);
    showLogin();
  };

  // ── Tabs ────────────────────────────────────────────────────────────
  const setTab = (tab) => {
    if (tab === 'approvals' && role() === 'role-clerk') tab = 'invoices';
    state.activeTab = tab;
    $('#invoices-section').hidden = tab !== 'invoices';
    $('#approvals-section').hidden = tab !== 'approvals';
    $('#import-section').hidden = tab !== 'import';
    $$('#tab-bar .tab-btn').forEach((btn) => {
      btn.classList.remove('bg-cyan-500/10', 'border-cyan-500/30', 'text-cyan-200');
      btn.classList.add('border-slate-700', 'text-slate-300');
    });
    const active = $(`#tab-${tab}`);
    if (active) {
      active.classList.add('bg-cyan-500/10', 'border-cyan-500/30', 'text-cyan-200');
      active.classList.remove('border-slate-700', 'text-slate-300');
    }
  };

  // ── Renders ─────────────────────────────────────────────────────────
  const renderEntitySwitcher = () => {
    const sel = $('#entity-switcher');
    const prev = sel.value;
    sel.innerHTML = '<option value="">All entities</option>' +
      state.entities.map((e) => `<option value="${e.id}">${e.name}</option>`).join('');
    if ([...sel.options].some((o) => o.value === prev)) sel.value = prev;
  };

  const renderBadge = () => {
    $('#role-badge').textContent = ROLE_LABELS[role()] || '';
    // Clerks don't get the approvals tab at all.
    $('#tab-approvals').style.display = role() === 'role-clerk' ? 'none' : '';
  };

  const visibleInvoices = () => {
    const eid = currentEntityId();
    return state.invoices.filter((i) => !eid || i.entityId === eid);
  };

  const renderKpis = () => {
    const inv = visibleInvoices();
    const total = inv.reduce((s, i) => s + Number(i.amount), 0);
    const cards = [
      ['Invoices', inv.length],
      ['Pending Approval', inv.filter((i) => i.status === 'Pending Approval').length],
      ['Approved', inv.filter((i) => i.status === 'Approved').length],
      ['Total', money(total)]
    ];
    $('#kpi-row').innerHTML = cards.map(([label, value]) =>
      `<div class="panel rounded-2xl border border-slate-800 bg-slate-900/70 p-4"><div class="text-sm text-slate-400">${label}</div><div class="mt-2 text-2xl font-semibold">${value}</div></div>`).join('');
  };

  const statusPill = (s) => {
    const map = {
      'Draft': 'bg-slate-500/15 text-slate-300 border-slate-500/30',
      'Pending Approval': 'bg-amber-500/15 text-amber-300 border-amber-500/30',
      'Approved': 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30',
      'Paid': 'bg-cyan-500/15 text-cyan-300 border-cyan-500/30',
      'Rejected': 'bg-rose-500/15 text-rose-300 border-rose-500/30'
    };
    return `<span class="inline-flex rounded-full border px-2.5 py-0.5 text-xs font-medium ${map[s] || map.Draft}">${s}</span>`;
  };

  const historyRow = (invoice) => {
    const h = invoice.history || [];
    const lines = h.length
      ? h.map((e) => `<div><span class="font-semibold text-slate-100">${e.action}</span> · ${ROLE_LABELS[e.role] || e.role || 'System'} · ${new Date(e.at).toLocaleString()}${e.reason ? ` · <span class="text-rose-300">${e.reason}</span>` : ''}</div>`).join('')
      : '<div class="text-slate-500">No approval history yet.</div>';
    return `<tr class="history-row bg-slate-950/80"><td colspan="5" class="px-4 py-3 text-sm text-slate-300"><div class="mb-1 text-xs uppercase tracking-wide text-slate-500">Approval history</div><div class="space-y-1">${lines}</div></td></tr>`;
  };

  const renderInvoices = () => {
    const rows = visibleInvoices().map((i) => {
      const submitBtn = i.status === 'Draft'
        ? `<button class="submit-btn rounded-lg border border-cyan-500/30 bg-cyan-500/10 px-3 py-1 text-xs text-cyan-200" data-invoice-id="${i.id}">Submit for Approval</button>`
        : (i.reason ? `<span class="text-xs text-rose-300">${i.reason}</span>` : '');
      return `<tr class="invoice-row cursor-pointer hover:bg-slate-900/60" data-invoice-id="${i.id}"><td class="px-4 py-3">${i.vendor}</td><td class="px-4 py-3">${entityName(i.entityId)}</td><td class="px-4 py-3">${money(i.amount)}</td><td class="px-4 py-3">${statusPill(i.status)}</td><td class="px-4 py-3">${submitBtn}</td></tr>`;
    }).join('');
    $('#invoices-tbody').innerHTML = rows || '<tr><td colspan="5" class="px-4 py-8 text-center text-slate-400">No invoices for this entity.</td></tr>';
  };

  const renderApprovals = () => {
    const rows = visibleInvoices().filter((i) => i.status === 'Pending Approval').map((i) => {
      const blocked = role() === 'role-manager' && Number(i.amount) > MANAGER_LIMIT;
      return `<tr data-invoice-row="${i.id}"><td class="px-4 py-3">${i.vendor}</td><td class="px-4 py-3">${entityName(i.entityId)}</td><td class="px-4 py-3 font-medium">${money(i.amount)}</td><td class="px-4 py-3">${statusPill(i.status)}</td><td class="px-4 py-3"><div class="flex gap-2"><button class="approve-btn rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-1.5 text-sm text-emerald-200 disabled:cursor-not-allowed disabled:opacity-50" data-invoice-id="${i.id}" ${blocked ? 'disabled title="Amounts over $10,000 need the Controller"' : ''}>${blocked ? 'Requires Controller' : 'Approve'}</button><button class="reject-btn rounded-lg border border-rose-500/30 bg-rose-500/10 px-3 py-1.5 text-sm text-rose-200" data-invoice-id="${i.id}">Reject</button></div></td></tr>`;
    }).join('');
    $('#approvals-tbody').innerHTML = rows || '<tr><td colspan="5" class="px-4 py-8 text-center text-slate-400">No pending approvals for this entity. 🎉</td></tr>';
  };

  const render = () => {
    renderBadge();
    renderKpis();
    renderInvoices();
    renderApprovals();
  };

  const persist = () => write(INV_KEY, state.invoices);
  const addHistory = (invoice, action, reason) => {
    invoice.history = invoice.history || [];
    invoice.history.push({ role: role(), action, reason: reason || null, at: new Date().toISOString() });
  };

  // ── Statement import & recurring detection ──────────────────────────
  const normalize = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const analyzeStatement = () => {
    const csv = $('#statement-csv')?.value || '';
    const lines = csv.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    const data = lines.slice(lines[0]?.toLowerCase().startsWith('date') ? 1 : 0);
    const txns = data.map((l) => l.split(',')).filter((p) => p.length >= 3)
      .map((p) => ({ date: p[0].trim(), desc: p[1].trim(), amount: Number(p[2]) }))
      .filter((t) => t.desc && Number.isFinite(t.amount));

    const groups = new Map();
    txns.forEach((t) => {
      const k = normalize(t.desc);
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(t);
    });

    const recurring = [];
    for (const items of groups.values()) {
      if (items.length < 3) continue;
      const avg = items.reduce((s, t) => s + t.amount, 0) / items.length;
      const maxDev = Math.max(...items.map((t) => Math.abs(t.amount - avg)));
      if (avg > 0 && maxDev / avg < 0.1) {
        // regular monthly cadence check: distinct months == occurrences
        const months = new Set(items.map((t) => t.date.slice(0, 7)));
        if (months.size >= 3) recurring.push({ vendor: items[0].desc, avg, count: items.length });
      }
    }

    $('#import-summary').textContent = `Analyzed ${txns.length} transactions — ${recurring.length} recurring vendors detected`;
    $('#recurring-list').innerHTML = recurring.map((r) =>
      `<div class="panel rounded-2xl border border-slate-800 bg-slate-900/70 p-4 space-y-2">
        <div class="flex items-center justify-between gap-2">
          <div class="font-semibold">${r.vendor}</div>
          <span class="rounded-full border border-cyan-500/30 bg-cyan-500/10 px-2 py-0.5 text-xs text-cyan-300">Monthly</span>
        </div>
        <div class="text-2xl font-semibold">${money(r.avg)}<span class="text-sm font-normal text-slate-400">/month avg</span></div>
        <div class="text-xs text-slate-400">${r.count} occurrences detected in statement</div>
        <button class="create-recurring-btn w-full rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-200 disabled:opacity-60" data-vendor="${r.vendor}" data-amount="${r.avg.toFixed(2)}">Create Recurring Invoice</button>
      </div>`).join('') || '<div class="text-sm text-slate-400">No recurring vendors detected.</div>';
  };

  // ── Event delegation ─────────────────────────────────────────────────
  document.addEventListener('click', (e) => {
    const approve = e.target.closest?.('.approve-btn');
    if (approve && !approve.disabled) {
      const inv = state.invoices.find((i) => i.id === approve.dataset.invoiceId);
      if (inv) { inv.status = 'Approved'; inv.reason = ''; addHistory(inv, 'Approved'); persist(); render(); }
      return;
    }
    const reject = e.target.closest?.('.reject-btn');
    if (reject) {
      const inv = state.invoices.find((i) => i.id === reject.dataset.invoiceId);
      if (!inv) return;
      const reason = prompt('Reason for rejection?');
      if (!reason) return;
      inv.status = 'Rejected'; inv.reason = reason; addHistory(inv, 'Rejected', reason); persist(); render();
      return;
    }
    const submit = e.target.closest?.('.submit-btn');
    if (submit) {
      const inv = state.invoices.find((i) => i.id === submit.dataset.invoiceId);
      if (inv) { inv.status = 'Pending Approval'; addHistory(inv, 'Submitted'); persist(); render(); }
      return;
    }
    const rec = e.target.closest?.('.create-recurring-btn');
    if (rec && !rec.disabled) {
      const eid = currentEntityId() || state.entities[0]?.id;
      state.invoices.push({
        id: 'inv_' + Date.now(), entityId: eid, vendor: rec.dataset.vendor,
        amount: Number(rec.dataset.amount), status: 'Draft', reason: '',
        history: [{ role: role(), action: 'Created from recurring detection', reason: null, at: new Date().toISOString() }]
      });
      persist(); render();
      rec.textContent = 'Invoice Created ✓'; rec.disabled = true;
      return;
    }
    const row = e.target.closest?.('.invoice-row');
    if (row && !e.target.closest('button')) {
      const inv = state.invoices.find((i) => i.id === row.dataset.invoiceId);
      if (!inv) return;
      const next = row.nextElementSibling;
      if (next && next.classList.contains('history-row')) { next.remove(); return; }
      row.insertAdjacentHTML('afterend', historyRow(inv));
    }
  });

  document.addEventListener('DOMContentLoaded', () => {
    $$('#role-clerk, #role-manager, #role-controller').forEach((card) => card.addEventListener('click', () => {
      chosenRole = card.id;
      $$('.role-card').forEach((c) => c.classList.remove('border-cyan-500/40', 'bg-cyan-500/10', 'ring-1', 'ring-cyan-500/30'));
      card.classList.add('border-cyan-500/40', 'bg-cyan-500/10', 'ring-1', 'ring-cyan-500/30');
    }));
    $('#login-form')?.addEventListener('submit', (e) => { e.preventDefault(); login(); });
    $('#logout-btn')?.addEventListener('click', logout);
    $('#tab-invoices')?.addEventListener('click', () => setTab('invoices'));
    $('#tab-approvals')?.addEventListener('click', () => setTab('approvals'));
    $('#tab-import')?.addEventListener('click', () => setTab('import'));
    $('#entity-switcher')?.addEventListener('change', render);
    $('#import-analyze-btn')?.addEventListener('click', analyzeStatement);
    $('#new-invoice-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const vendor = $('#invoice-vendor').value.trim();
      const amount = Number($('#invoice-amount').value);
      if (!vendor || !Number.isFinite(amount) || amount <= 0) return;
      const eid = currentEntityId() || state.entities[0]?.id;
      state.invoices.push({ id: 'inv_' + Date.now(), entityId: eid, vendor, amount, status: 'Draft', reason: '', history: [{ role: role(), action: 'Created', reason: null, at: new Date().toISOString() }] });
      persist(); render();
      $('#invoice-vendor').value = ''; $('#invoice-amount').value = '';
    });
    load();
  });
})();

from fastapi import FastAPI, HTTPException, Header, Response
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field
from typing import Any, Optional, Literal
from uuid import uuid4
from datetime import datetime, timezone

app = FastAPI(title="AP Demo Backend", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"
DEMO_USER = {
    "id": "user_demo",
    "email": DEMO_EMAIL,
    "name": "Demo User",
    "role": "controller",
    "createdAt": "2025-01-01T00:00:00Z",
}

TOKENS: dict[str, dict[str, Any]] = {}
ENTITIES: dict[str, dict[str, Any]] = {}
INVOICES: dict[str, dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def get_user_from_token(authorization: Optional[str]) -> dict[str, Any]:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing or invalid Authorization header")
    token = authorization.removeprefix("Bearer ").strip()
    user = TOKENS.get(token)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    return user


class LoginReq(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1)


class LoginResp(BaseModel):
    token: str
    user: dict[str, Any]


class EntityCreateReq(BaseModel):
    title: str = Field(min_length=1)
    amount: float = Field(ge=0)
    description: Optional[str] = None


class InvoiceCreateReq(BaseModel):
    entityId: str = Field(min_length=1)
    vendor: str = Field(min_length=1)
    amount: float = Field(ge=0)
    status: str = Field(default="Draft")
    approvalReason: Optional[str] = None


class InvoiceActionReq(BaseModel):
    reason: Optional[str] = None


@app.get("/api/health")
def health():
    return {"status": "ok", "version": app.version}


@app.post("/api/auth/login", response_model=LoginResp)
def login(req: LoginReq):
    if req.email.lower() != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = uuid4().hex
    TOKENS[token] = DEMO_USER.copy()
    return {"token": token, "user": DEMO_USER}


@app.get("/api/auth/me")
def me(authorization: Optional[str] = Header(default=None)):
    return get_user_from_token(authorization)


@app.get("/api/entities")
def list_entities(authorization: Optional[str] = Header(default=None)):
