@app.get("/api/invoices")
def list_invoices(authorization: Optional[str] = Header(default=None)):
    get_user_from_token(authorization)
    return list(INVOICES.values())


@app.post("/api/invoices")
def create_invoice(req: InvoiceCreateReq, authorization: Optional[str] = Header(default=None)):
    user = get_user_from_token(authorization)
    invoice_id = uuid4().hex
    invoice = {
        "id": invoice_id,
        "entityId": req.entityId,
        "vendor": req.vendor,
        "amount": req.amount,
        "status": req.status,
        "approvalReason": req.approvalReason,
        "createdAt": now_iso(),
        "updatedAt": now_iso(),
        "history": [{"who": user["role"], "role": user["role"], "action": "Created", "timestamp": now_iso(), "reason": None}],
    }
    INVOICES[invoice_id] = invoice
    return invoice


@app.post("/api/invoices/{invoice_id}/approve")
def approve_invoice(invoice_id: str, authorization: Optional[str] = Header(default=None)):
    user = get_user_from_token(authorization)
    invoice = INVOICES.get(invoice_id)
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    invoice["status"] = "Approved"
    invoice["approvalReason"] = None
    invoice.setdefault("history", []).append({"who": user["name"], "role": user["role"], "action": "Approved", "timestamp": now_iso(), "reason": None})
    invoice["updatedAt"] = now_iso()
    return invoice


@app.post("/api/invoices/{invoice_id}/reject")
def reject_invoice(invoice_id: str, req: InvoiceActionReq, authorization: Optional[str] = Header(default=None)):
    user = get_user_from_token(authorization)
    invoice = INVOICES.get(invoice_id)
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    reason = (req.reason or "").strip()
    if not reason:
        raise HTTPException(status_code=400, detail="Reason is required")
    invoice["status"] = "Rejected"
    invoice["approvalReason"] = reason
    invoice.setdefault("history", []).append({"who": user["name"], "role": user["role"], "action": "Rejected", "timestamp": now_iso(), "reason": reason})
    invoice["updatedAt"] = now_iso()
    return invoice


